<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?= esc($title) ?></title><style>
*{box-sizing:border-box}body{margin:0;padding:28px;font-family:Segoe UI,Arial,sans-serif;color:#203244;background:linear-gradient(135deg,#edf5f7,#f8fafc)}main{max-width:1120px;margin:auto}.hero,.panel{border:1px solid #fff;border-radius:20px;background:rgba(255,255,255,.8);backdrop-filter:blur(15px);box-shadow:0 12px 32px #183b5612;padding:24px;margin-bottom:18px}h1{margin:0;color:#183b56}.muted{color:#667b8e;margin-top:6px}.btn{display:inline-block;padding:10px 15px;border-radius:12px;text-decoration:none;background:linear-gradient(135deg,#2e6f8f,#397f8e);color:#fff;font-weight:700;border:0;cursor:pointer}.success,.error{padding:12px;border-radius:12px;margin-bottom:14px}.success{background:#e8f5ef;color:#27664b}.error{background:#fff0ef;color:#8d3835}.table-wrap{overflow:auto}table{width:100%;border-collapse:collapse}th,td{text-align:left;padding:12px;border-bottom:1px solid #e2ebef;vertical-align:top}th{font-size:12px;text-transform:uppercase;letter-spacing:.05em;color:#60798a}td{font-size:14px}.pill{display:inline-block;padding:5px 9px;border-radius:20px;background:#e4f0f2;color:#2d6873;font-size:12px;font-weight:700}.empty{padding:28px;text-align:center;color:#667b8e}@media(max-width:650px){body{padding:12px}}
</style></head><body><main><header class="hero"><h1>My Draft Questions</h1><div class="muted">Drafts are private to your account. Submitting changes status to Submitted; online approval is not available.</div><p><a class="btn" href="<?= site_url('master/mcqs/new') ?>">＋ Create MCQ</a></p></header><?php foreach(['success','error'] as $type): if($m=session()->getFlashdata($type)): ?><div class="<?= $type ?>"><?= esc($m) ?></div><?php endif; endforeach ?><section class="panel"><div class="table-wrap"><table><thead><tr><th>ID</th><th>Stem / Lead-in</th><th>Curriculum</th><th>Difficulty</th><th>Saved</th><th>Action</th></tr></thead><tbody><?php if(!$questions): ?><tr><td colspan="6" class="empty">No draft questions yet. Select “Create MCQ” to begin.</td></tr><?php endif ?><?php foreach($questions as $q): ?><tr><td><?= esc($q['mcq_id']) ?></td><td><strong><?= esc(mb_strimwidth((string)$q['stem'],0,110,'…')) ?></strong><div class="muted"><?= esc(mb_strimwidth((string)$q['leadin'],0,100,'…')) ?></div></td><td><?= esc($q['subject_name']??'') ?><div class="muted"><?= esc($q['system']??'') ?> · <?= esc($q['topic']??'') ?></div></td><td><span class="pill"><?= esc($q['difficulty']) ?></span></td><td><?= esc($q['mdate']) ?></td><td><form method="post" action="<?= site_url('master/mcqs/submit/'.(int)$q['mcq_id']) ?>"><?= csrf_field() ?><button class="btn" onclick="return confirm('Submit this question to the administrator?');">Submit</button></form></td></tr><?php endforeach ?></tbody></table></div></section></main></body></html>
